// Adapters preserve the Espressif callback ABI; buffer bounds are independently testable.
static size_t readJpeg(void* argument, size_t index, uint8_t* buffer, size_t length) {
  return static_cast<JpegBuffer*>(argument)->read(index, buffer, length);
}
static bool writeJpegTile(void* argument, uint16_t x, uint16_t y, uint16_t width, uint16_t height, uint8_t* data) {
  return static_cast<JpegBuffer*>(argument)->write(x, y, width, height, data);
}

bool CameraService::begin() {
  const bool hasPsram = psramFound();
  const uint32_t psramSize = ESP.getPsramSize();
  if (!hasPsram || psramSize == 0) {
    Serial.printf("Cinema camera: PSRAM unavailable (found=%s, size=%lu bytes)\n", hasPsram ? "yes" : "no", static_cast<unsigned long>(psramSize));
    return false;
  }

  camera_config_t config = {};
  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer = LEDC_TIMER_0;
  config.pin_d0 = pins::Y2;
  config.pin_d1 = pins::Y3;
  config.pin_d2 = pins::Y4;
  config.pin_d3 = pins::Y5;
  config.pin_d4 = pins::Y6;
  config.pin_d5 = pins::Y7;
  config.pin_d6 = pins::Y8;
  config.pin_d7 = pins::Y9;
  config.pin_xclk = pins::XCLK;
  config.pin_pclk = pins::PCLK;
  config.pin_vsync = pins::VSYNC;
  config.pin_href = pins::HREF;
  config.pin_sccb_sda = pins::SIOD;
  config.pin_sccb_scl = pins::SIOC;
  config.pin_pwdn = pins::PWDN;
  config.pin_reset = pins::RESET;
  config.xclk_freq_hz = 20000000;
  config.pixel_format = PIXFORMAT_JPEG;
  config.frame_size = FRAMESIZE_VGA; // Reserve JPEG buffers for on-demand calibration photos.
  config.jpeg_quality = 12;
  // JPEG permits continuous capture with two buffers, as in Espressif CameraWebServer:
  // https://github.com/espressif/esp32-camera#important-to-remember
  config.fb_count = 2;
  config.fb_location = CAMERA_FB_IN_PSRAM;
  config.grab_mode = CAMERA_GRAB_LATEST;
  _decoded = static_cast<uint8_t*>(heap_caps_malloc(DECODED_SIZE, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT));
  if (!_decoded) return false;

  const esp_err_t initResult = esp_camera_init(&config);
  _ready = initResult == ESP_OK;
  if (!_ready) Serial.printf("Cinema camera: esp_camera_init failed: %s (0x%lx)\n", esp_err_to_name(initResult), static_cast<unsigned long>(initResult));
  if (!_ready) { heap_caps_free(_decoded); _decoded = nullptr; return false; }
  sensor_t* sensor = esp_camera_sensor_get();
  if (!sensor || sensor->id.PID != OV2640_PID) {
    Serial.println("Cinema camera: an OV2640 sensor is required");
    esp_camera_deinit(); heap_caps_free(_decoded); _decoded = nullptr; _ready = false;
    return false;
  }
  Serial.printf("Cinema camera: OV2640 JPEG initialized, PSRAM=%lu, stream=160x120, photo=640x480\n", static_cast<unsigned long>(psramSize));
  if (!resumeStream()) return false;
  // Verify the real sensor/decoder path before SPI starts; transient startup frames may be invalid.
  for (uint8_t attempt = 0; attempt < 3; attempt++) {
    camera_fb_t* frame = acquire();
    const uint32_t started = millis();
    const bool valid = decode(frame) != nullptr;
    Serial.printf("Cinema JPEG self-check: %ux%u, %u bytes, decode=%s, %lu ms\n",
      frame ? static_cast<unsigned>(frame->width) : 0, frame ? static_cast<unsigned>(frame->height) : 0,
      frame ? static_cast<unsigned>(frame->len) : 0, valid ? "ok" : "failed", static_cast<unsigned long>(millis() - started));
    release(frame);
    if (valid) return true;
  }
  return false;
}

// Only the capture task writes sensor registers. Failed updates stop publication until
// a bounded retry succeeds, rather than advertising new settings over an old image.
bool CameraService::configure(const Settings& settings) {
  if (!_ready || !settings.isValid()) return false;
  if (_configured && _streamReady && _settings == settings) return true;
  const uint32_t now = millis();
  if (_retryPending && static_cast<uint32_t>(now - _lastConfigureAttempt) < 1000) return false;
  _lastConfigureAttempt = now;
  sensor_t* s = esp_camera_sensor_get();
  bool ok = s && s->set_brightness(s, settings.brightness) == 0 && s->set_contrast(s, settings.contrast) == 0
      && s->set_saturation(s, settings.saturation) == 0 && s->set_ae_level(s, settings.aeLevel) == 0
      && s->set_gainceiling(s, static_cast<gainceiling_t>(settings.gainCeiling)) == 0
      && s->set_whitebal(s, settings.whiteBalance) == 0 && s->set_wb_mode(s, settings.wbMode) == 0
      && s->set_gain_ctrl(s, settings.autoGain) == 0 && s->set_exposure_ctrl(s, settings.autoExposure) == 0
      && s->set_quality(s, settings.jpegQuality) == 0;
  if (ok && !settings.autoGain) ok = s->set_agc_gain(s, settings.gain) == 0;
  if (ok && !settings.autoExposure) ok = s->set_aec_value(s, settings.exposure) == 0;
  _configured = ok;
  if (ok) { _settings = settings; ok = _streamReady || resumeStream(); }
  _retryPending = !ok;
  if (!ok) Serial.println("Cinema camera: sensor settings failed, retrying after 1 second");
  return ok;
}

// Switch resolution without changing JPEG capture mode or reallocating framebuffers.
// Drain queued frames so a photo can never be an enlarged old streaming image.
camera_fb_t* CameraService::capturePreview() {
  sensor_t* s = esp_camera_sensor_get();
  _streamReady = false;
  if (!s || s->set_framesize(s, FRAMESIZE_VGA) != 0) return nullptr;
  for (uint8_t attempt = 0; attempt < 4; attempt++) {
    const uint8_t quality = std::min<int>(40, _settings.jpegQuality + attempt * 8);
    if (s->set_quality(s, quality) != 0) break;
    for (uint8_t discard = 0; discard < 2; discard++) release(esp_camera_fb_get());
    camera_fb_t* frame = esp_camera_fb_get();
    uint16_t width = 0, height = 0;
    if (frame && frame->format == PIXFORMAT_JPEG && frame->width == preview::WIDTH && frame->height == preview::HEIGHT
        && frame->len <= preview::MAX_IMAGE_SIZE && preview::jpegDimensions(frame->buf, frame->len, &width, &height)
        && width == frame->width && height == frame->height) return frame;
    release(frame);
  }
  return nullptr;
}

// Restore the LED capture size and normal quality even when the photo failed or was cancelled.
bool CameraService::resumeStream() {
  sensor_t* s = esp_camera_sensor_get();
  _streamReady = s && s->set_framesize(s, FRAMESIZE_QQVGA) == 0 && s->set_quality(s, _settings.jpegQuality) == 0;
  if (_streamReady) for (uint8_t i = 0; i < 2; i++) release(esp_camera_fb_get());
  return _streamReady;
}

// Decode a small JPEG with full 8-bit channels for the LED sampler. Higher resolution
// belongs to on-demand photos; decoding a VGA frame for every LED update is too slow.
const uint8_t* CameraService::decode(camera_fb_t* frame) {
  uint16_t width = 0, height = 0;
  if (!frame || frame->format != PIXFORMAT_JPEG || frame->width != CAPTURE_WIDTH || frame->height != CAPTURE_HEIGHT
      || !preview::jpegDimensions(frame->buf, frame->len, &width, &height) || width != CAPTURE_WIDTH || height != CAPTURE_HEIGHT) return nullptr;
  JpegBuffer context{frame->buf, frame->len, _decoded, STREAM_WIDTH, STREAM_HEIGHT, DECODED_SIZE};
  return esp_jpg_decode(frame->len, JPG_SCALE_NONE, readJpeg, writeJpegTile, &context) == ESP_OK
      && context.written == static_cast<uint32_t>(STREAM_WIDTH) * STREAM_HEIGHT ? _decoded : nullptr;
}

